487	    display: flex;
488	  }
489	
490	  .nav-link {
491	    padding: var(--space-3);
492	  }
493	
494	  .cards,
495	  .cards-4,
496	  .stats {
497	    grid-template-columns: 1fr;
498	  }
499	
500	  .footer-inner {
501	    flex-direction: column;
502	    align-items: flex-start;
503	  }
504	}
