const { chromium } = require('/var/tmp/avb-runs/avb-VLyBEN/project/node_modules/playwright');
const { spawn } = require('node:child_process');
const path = require('node:path');
const srv = spawn(process.execPath, ['server.js'], { cwd: '/var/tmp/avb-runs/avb-VLyBEN/project', env: { ...process.env, PORT: '4199' }, stdio: 'ignore' });
(async () => {
  await new Promise(r => setTimeout(r, 800));
  const browser = await chromium.launch();
  for (const [name, w, h] of [['desktop', 1280, 900], ['mobile', 390, 844]]) {
    const page = await browser.newPage({ viewport: { width: w, height: h } });
    const errors = [];
    page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
    await page.goto('http://127.0.0.1:4199/products.html', { waitUntil: 'networkidle' });
    await page.screenshot({ path: path.join(process.env.TMPDIR, `products-${name}.png`), fullPage: true });
    const info = await page.evaluate(() => {
      const cards = [...document.querySelectorAll('.card.product')];
      const r = el => { const b = el.getBoundingClientRect(); return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height) }; };
      return {
        bodyScrollWidth: document.documentElement.scrollWidth,
        viewport: window.innerWidth,
        cardCount: cards.length,
        cards: cards.map(c => ({ rect: r(c), thumb: r(c.querySelector('.card-thumb')), badge: c.querySelector('.badge') ? { rect: r(c.querySelector('.badge')), visible: !!(c.querySelector('.badge').offsetWidth || c.querySelector('.badge').offsetHeight) } : null })),
        gridCols: getComputedStyle(document.querySelector('.cards')).gridTemplateColumns,
      };
    });
    console.log(name, JSON.stringify(info, null, 1), 'errors:', errors);
    await page.close();
  }
  await browser.close();
  srv.kill();
  process.exit(0);
})().catch(e => { console.error(e); srv.kill(); process.exit(1); });
EOF
