      if (file === 'products.html') await page.screenshot({ path: path.join(process.env.TMPDIR, `fixed-products-${name}.png`), fullPage: true });
      if (file === 'index.html' && name === 'desktop') await page.screenshot({ path: path.join(process.env.TMPDIR, `fixed-index-${name}.png`), fullPage: true });
    }
    await page.close();
  }
  await browser.close(); srv.kill(); process.exit(0);
})().catch(e => { console.error(e); srv.kill(); process.exit(1); });
EOF
